const channel = MethodChannel('app/reminders');

void onSetReminder(BuildContext context, Reminder r) {
  // Not awaited, and DateTime isn't a codec type:
  // the ArgumentError lands in a Future nobody listens to
  channel.invokeMethod('schedule', {'id': r.id, 'at': r.at});
  ScaffoldMessenger.of(context)
      .showSnackBar(const SnackBar(content: Text('Reminder set')));
}

const channel = MethodChannel('app/reminders');

Future<void> onSetReminder(BuildContext context, Reminder r) async {
  final messenger = ScaffoldMessenger.of(context);
  try {
    await channel.invokeMethod<void>('schedule', {
      'id': r.id,
      'at': r.at.millisecondsSinceEpoch, // an int crosses the channel
    });
    messenger.showSnackBar(const SnackBar(content: Text('Reminder set')));
  } on PlatformException catch (e) {
    messenger.showSnackBar(SnackBar(content: Text('Failed: ${e.message}')));
  }
}

